/* nano5g bootstub — sysfont.h
 *
 * The vendored Rockbox sources include "sysfont.h", which in a real
 * Rockbox build is generated by convbdf from the system BDF font.
 * Only the font METRICS matter to the code compiled here (the boot
 * messages are drawn by this bootstub's own lcd5g.c/bootfont.c, not
 * by Rockbox's font renderer). The one macro actually referenced is
 * SYSFONT_HEIGHT (bootloader/common.c, splash line layout); the other
 * stock metrics are kept for completeness. These are the standard
 * rockbox system-font (08-Schumacher-Clean) values.
 */
#ifndef __SYSFONT_H__
#define __SYSFONT_H__

#define SYSFONT_WIDTH          6
#define SYSFONT_HEIGHT         8
#define SYSFONT_ASCENT         7
#define SYSFONT_DESCENT        1
#define SYSFONT_FIRST_CHAR     0
#define SYSFONT_LAST_CHAR      126

#endif /* __SYSFONT_H__ */
